// src/components/ReviewModal.js

import React, { useState, useEffect } from 'react';
import Modal from 'react-modal';
import MovieSearchBar from './MovieSearchBar';
import { getPosterFromTMDB } from '../api/tmdbApi'; // API 재사용

// Modal의 root 엘리먼트 설정 (접근성)
Modal.setAppElement('#root');

function ReviewModal({ isOpen, onRequestClose, date, existingReview, onSave }) {
  const [movie, setMovie] = useState(null);
  const [reviewText, setReviewText] = useState('');
  const [posterPath, setPosterPath] = useState('');

  useEffect(() => {
    // 기존 리뷰가 있으면 데이터 채우기
    if (existingReview) {
      setMovie(existingReview.movie);
      setReviewText(existingReview.reviewText);
      setPosterPath(existingReview.posterPath);
    } else {
      // 새 리뷰 작성 시 초기화
      setMovie(null);
      setReviewText('');
      setPosterPath('');
    }
  }, [existingReview]);

  const handleMovieSelect = async (selectedMovie) => {
    setMovie(selectedMovie);
    const year = selectedMovie.openDt?.substring(0, 4) || "";
    const poster = await getPosterFromTMDB(selectedMovie.movieNm, year, {
      movieNmEn: selectedMovie.movieNmEn,
      nation: selectedMovie.repNationNm,
    });
    setPosterPath(poster || '');
  };

  const handleSave = () => {
    if (!movie) {
      alert('영화를 선택해주세요.');
      return;
    }
    onSave({
      date,
      movie,
      reviewText,
      posterPath,
    });
    onRequestClose(); // 저장 후 모달 닫기
  };

  return (
    <Modal
      isOpen={isOpen}
      onRequestClose={onRequestClose}
      className="review-modal"
      overlayClassName="review-modal-overlay"
    >
      <h2>{date.toLocaleDateString()} 리뷰</h2>
      <MovieSearchBar onMovieSelect={handleMovieSelect} />
      
      {movie && (
        <div className="selected-movie-info">
          {posterPath && <img src={posterPath} alt={movie.movieNm} />}
          <h3>{movie.movieNm}</h3>
        </div>
      )}

      <textarea
        value={reviewText}
        onChange={(e) => setReviewText(e.target.value)}
        placeholder="리뷰를 작성하세요..."
        rows="5"
      />
      <div className="modal-buttons">
        <button onClick={handleSave} className="save-btn">저장</button>
        <button onClick={onRequestClose} className="cancel-btn">취소</button>
      </div>
    </Modal>
  );
}

export default ReviewModal;
